class PalindromeMaker:
    def __init__(self, string: str):
        self.string = string

    def is_palindrome(self, s: str) -> bool:
        """ Test if given string is a palindrome """
        return s == s[::-1]

    def make_palindrome(self) -> str:
        """ Find the shortest palindrome that begins with a supplied string """
        if not self.string:
            return ''

        for i in range(len(self.string), 0, -1):
            postfix = self.string[-i:]
            if self.is_palindrome(postfix):
                return self.string + postfix + self.reverse_prefix(self.string[:-i])

        return self.string

    def reverse_prefix(self, s: str) -> str:
        """ Reverse the prefix of a string """
        return s[::-1]

# Usage
maker = PalindromeMaker('cata')
print(maker.make_palindrome())  # Output: catac

