class PalindromeFinder:
    def __init__(self, string: str):
        self.string = string

    def is_palindrome(self, s: str) -> bool:
        """Test if given string is a palindrome"""
        return s == s[::-1]

    def find_longest_palindromic_suffix(self) -> str:
        """Find the longest postfix of the input string that is a palindrome"""
        for i in range(len(self.string), 0, -1):
            if self.is_palindrome(self.string[i:]):
                return self.string[i:]
        return ""

    def make_palindrome(self) -> str:
        """Find the shortest palindrome that begins with a supplied string"""
        if not self.string:
            return ''
        suffix = self.find_longest_palindromic_suffix()
        prefix = self.string[:self.string.index(suffix)]
        return suffix + prefix[::-1]

